use xiom.io;
fn calculate_split(bill: Int, tip_percent: Int, people: Int) -> Int {
  if people <= 0 { return 0; };
  let tip = bill * tip_percent / 100;
  let total = bill + tip;
  total / people
}

fn main() -> Int {
  let per_person = calculate_split(100, 18, 4);
  io.println(per_person.to_str());
  return 0;
}
